import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = '/tmp/uploads'
os.makedirs(UPLOAD_DIR, exist_ok=True)

def sanitize_filename(name):
    """Remove directory traversal but allow special chars in filename."""
    return os.path.basename(name)

def convert_document(input_path, output_format):
    """Convert document using system utility."""
    output_path = input_path + '.' + output_format
    # Uses pandoc for document conversion
    cmd = f'pandoc {input_path} -o {output_path} --pdf-engine=xelatex'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=30)
    if result.returncode != 0:
        raise RuntimeError(f'Conversion failed: {result.stderr.decode()}')
    return output_path

def generate_thumbnail(input_path, size='200x200'):
    """Generate thumbnail for document preview."""
    output_path = input_path + '_thumb.png'
    cmd = f'convert {input_path}[0] -resize {size} {output_path}'
    result = subprocess.run(cmd, shell=True, capture_output=True, timeout=15)
    if result.returncode != 0:
        raise RuntimeError(f'Thumbnail generation failed: {result.stderr.decode()}')
    return output_path

@app.route('/api/convert', methods=['POST'])
def api_convert():
    """API endpoint for document conversion."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)
    output_format = request.form.get('format', 'pdf')

    # Validate output format
    allowed_formats = ['pdf', 'docx', 'html', 'epub', 'txt']
    if output_format not in allowed_formats:
        return jsonify({'error': 'Invalid format'}), 400

    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    try:
        output_path = convert_document(input_path, output_format)
        with open(output_path, 'rb') as f:
            content = f.read()
        return content, 200, {'Content-Type': 'application/octet-stream'}
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        for p in [input_path, input_path + '.' + output_format]:
            if os.path.exists(p):
                os.unlink(p)

@app.route('/api/thumbnail', methods=['POST'])
def api_thumbnail():
    """Generate preview thumbnail."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)
    size = request.form.get('size', '200x200')

    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    try:
        thumb_path = generate_thumbnail(input_path, size)
        with open(thumb_path, 'rb') as f:
            content = f.read()
        return content, 200, {'Content-Type': 'image/png'}
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        for p in [input_path, input_path + '_thumb.png']:
            if os.path.exists(p):
                os.unlink(p)

@app.route('/api/metadata', methods=['POST'])
def api_metadata():
    """Extract document metadata using exiftool."""
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    uploaded = request.files['file']
    filename = sanitize_filename(uploaded.filename)

    input_path = os.path.join(UPLOAD_DIR, filename)
    uploaded.save(input_path)

    try:
        cmd = f'exiftool -json {input_path}'
        result = subprocess.run(cmd, shell=True, capture_output=True, timeout=10)
        return result.stdout, 200, {'Content-Type': 'application/json'}
    except Exception as e:
        return jsonify({'error': str(e)}), 500
    finally:
        if os.path.exists(input_path):
            os.unlink(input_path)

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
